//! Browser conveniences for registration, email verification and recovery.
//! Protocol handlers remain JSON APIs; this view never handles raw credentials
//! server-side, and never places recovery tokens in URLs.
use axum::response::Html;

pub async fn page() -> Html<String> {
    crate::ui::render(
        "Compte",
        "/account",
        r####"<div class="page-heading"><div class="eyebrow">Donnarieix Auth</div><h1>Se connecter à votre compte</h1><p class="lead">Utilisez votre identité Donnarieix pour accéder aux applications que vous avez autorisées.</p></div><div class="columns"><section class="panel"><div class="segmented" role="tablist" aria-label="Gestion du compte"><button type="button" role="tab" aria-selected="true" data-tab="signin">Connexion</button><button type="button" role="tab" aria-selected="false" data-tab="signup">Inscription</button> </div><div class="view" data-view="signin"><h2>Connexion</h2><form data-path="/login"><label>Adresse email<input type="email" name="email" required autocomplete="email"></label><label>Mot de passe<input type="password" name="password" required autocomplete="current-password"></label><button type="submit">Me connecter</button></form></div><div class="view" data-view="signup" hidden><h2>Créer un compte</h2><form data-path="/register"><label>Adresse email<input type="email" name="email" required autocomplete="email" placeholder="vous@exemple.fr"></label><label>Identifiant<input name="username" required autocomplete="username" placeholder="Votre identifiant"></label><label>Mot de passe<input type="password" name="password" required autocomplete="new-password" minlength="12" placeholder="Au moins 12 caractères"></label><button type="submit">Créer mon compte</button></form></div><div class="view" data-view="verify" hidden><h2>Vérifier mon adresse email</h2><p class="muted">Saisissez le code unique reçu à votre adresse email.</p><form data-path="/email/verification/confirm"><label>Code de vérification<input name="token" required autocomplete="off"></label><button type="submit">Confirmer mon adresse</button></form><details style="margin-top:22px"><summary>Je n'ai pas reçu de code</summary><form style="margin-top:14px" data-path="/email/verification/request"><label>Adresse email<input type="email" name="email" required></label><button type="submit" class="secondary">Renvoyer un code</button></form></details></div><div class="view" data-view="recover" hidden><h2>Retrouver l'accès</h2><p class="muted">Demandez un code pour définir un nouveau mot de passe.</p><form data-path="/password/reset/request"><label>Adresse email<input type="email" name="email" required></label><button type="submit">Recevoir un code</button></form><details style="margin-top:22px"><summary>J'ai déjà mon code</summary><form data-path="/password/reset/confirm" style="margin-top:14px"><label>Code de récupération<input name="token" required autocomplete="off"></label><label>Nouveau mot de passe<input type="password" name="new_password" required autocomplete="new-password" minlength="12"></label><button type="submit">Mettre à jour le mot de passe</button></form></details></div><div class="account-links"><button class="secondary" type="button" data-tab="verify">Vérifier mon adresse</button><button class="secondary" type="button" data-tab="recover">Mot de passe oublié ?</button></div><p class="status" id="status" role="status" aria-live="polite"></p></section><aside class="stack"><section class="panel" data-auth-only hidden><h2>Votre espace personnel</h2><p class="muted">Consultez votre profil et les autorisations accordées aux applications.</p><a class="button secondary" href="/account/profile">Ouvrir mon profil</a></section><section class="panel" data-auth-only hidden><h2>Vos autorisations</h2><p class="muted">Une application doit demander votre accord avant d'accéder à vos informations.</p><a href="/account/permissions">Voir mes applications liées</a></section><section class="panel" data-guest-only><h2>Pour commencer</h2><p class="muted">Créez un compte, confirmez l'adresse email grâce au code reçu, puis connectez-vous. Les applications demanderont votre accord avant d'accéder à vos données.</p></section></aside></div><script>
const status=document.getElementById('status');
fetch('/me',{credentials:'same-origin',cache:'no-store'}).then(r=>{if(r.ok)location.replace('/account/profile');}).catch(()=>{});
document.querySelectorAll('[data-tab]').forEach(tab=>tab.addEventListener('click',()=>{document.querySelectorAll('[data-tab]').forEach(t=>t.setAttribute('aria-selected',String(t===tab)));document.querySelectorAll('[data-view]').forEach(view=>view.hidden=view.dataset.view!==tab.dataset.tab);status.textContent='';}));
document.querySelectorAll('form[data-path]').forEach(form=>form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button[type=submit]');button.disabled=true;status.textContent='Envoi en cours…';status.dataset.error='false';try{const res=await fetch(form.dataset.path,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))});status.textContent=res.ok?'Demande prise en compte. Consultez votre messagerie si un code est nécessaire.':res.status===403?'Requête refusée. Rechargez la page via votre adresse HTTPS.':'Impossible de traiter la demande. Vérifiez les champs et réessayez.';status.dataset.error=String(!res.ok);if(res.ok){const path=form.dataset.path;form.reset();if(path==='/login'){window.location.assign('/account/profile');return;}if(path==='/register'){document.querySelector('[data-tab="verify"]').click();status.textContent='Si votre inscription est prise en compte, vous recevrez un code de vérification par email.';}else if(path==='/email/verification/confirm'){document.querySelector('[data-tab="signin"]').click();status.textContent='Adresse vérifiée. Vous pouvez vous connecter.';}else if(path==='/password/reset/confirm'){document.querySelector('[data-tab="signin"]').click();status.textContent='Mot de passe mis à jour. Connectez-vous avec le nouveau mot de passe.';}}}catch{status.textContent='Serveur injoignable.';status.dataset.error='true';}finally{button.disabled=false;}}));
</script>"####,
    )
}
